def S(id, lec, src, kind, title, rows, note=None, subtitle=None):
    out = []
    for r in rows:
        d = {"part": r[0], "meaning": r[1], "example": r[2], "definition": r[3]}
        if len(r) > 4 and r[4]:
            d["note"] = r[4]
        out.append(d)
    s = {"id": id, "lec": lec, "src": src, "kind": kind, "title": title, "rows": out}
    if note: s["note"] = note
    if subtitle: s["subtitle"] = subtitle
    return s


